Steps:
[AUTH role=ORG_USER]
[GQL-OP setup_org_user]
  query { me { id } }
[GQL-EXEC setup_org_user]
[GQL-CAPTURE setup_org_user.data.me.id → USER_ID]
[GQL-OP cleanup_org_pre]
  mutation { clearCart(command: { storeId: "{{STORE_ID}}" userId: "{{USER_ID}}" }) { id } }
[GQL-EXEC cleanup_org_pre]
[GQL-OP cleanup_src_pre]
  mutation { clearCart(command: { cartName: "AGENT-TEST-CFG046-SRC" storeId: "{{STORE_ID}}" userId: "{{USER_ID}}" }) { id } }
[GQL-EXEC cleanup_src_pre]
[GQL-OP get_def]
  query { productConfiguration(configurableProductId: "@td(CFG_LAPTOP.id)" storeId: "{{STORE_ID}}") { configurationSections { id options { product { id } } } } }
[GQL-EXEC get_def]
[GQL-CAPTURE get_def.data.productConfiguration.configurationSections.0.id → SECTION_RAM_ID]
[GQL-CAPTURE get_def.data.productConfiguration.configurationSections.0.options.1.product.id → OPT_RAM_UPGRADE_ID]
[GQL-CAPTURE get_def.data.productConfiguration.configurationSections.1.id → SECTION_STORAGE_ID]
[GQL-CAPTURE get_def.data.productConfiguration.configurationSections.1.options.1.product.id → OPT_STORAGE_UPGRADE_ID]
[GQL-OP add_item_src]
[GQL-VARS add_item_src] {"configurationSections": [{"sectionId": "{{SECTION_RAM_ID}}", "type": "Product", "option": {"productId": "{{OPT_RAM_UPGRADE_ID}}", "quantity": 1}}, {"sectionId": "{{SECTION_STORAGE_ID}}", "type": "Product", "option": {"productId": "{{OPT_STORAGE_UPGRADE_ID}}", "quantity": 1}}]}
  mutation AddItem($configurationSections: [ConfigurationSectionInput]) {
    addItem(command: { cartName: "AGENT-TEST-CFG046-SRC" storeId: "{{STORE_ID}}" userId: "{{USER_ID}}" productId: "@td(CFG_LAPTOP.id)" quantity: 1 configurationSections: $configurationSections }) { id itemsCount items { id productId configurationItems { id sectionId productId selectedForCheckout } }
    }
  }
[GQL-EXEC add_item_src]
[GQL-CAPTURE add_item_src.data.addItem.id → SOURCE_CART_ID]
[GQL-OP merge]
  mutation {
    mergeCart(command: { storeId: "{{STORE_ID}}" userId: "{{USER_ID}}" secondCartId: "{{SOURCE_CART_ID}}" currencyCode: "USD" cultureName: "en-US" }) {
      id itemsCount items { id productId configurationItems { id sectionId productId selectedForCheckout } }
    }
  }
[GQL-EXEC merge]
[GQL-OP read_back]
  query { cart(storeId: "{{STORE_ID}}" currencyCode: "USD" userId: "{{USER_ID}}") { id itemsCount items { id productId configurationItems { id sectionId productId selectedForCheckout } } } }
[GQL-EXEC read_back]
[GQL-OP cleanup_post]
  mutation { clearCart(command: { storeId: "{{STORE_ID}}" userId: "{{USER_ID}}" }) { id } }
[GQL-EXEC cleanup_post]
[GQL-OP cleanup_src]
  mutation { removeCart(command: { cartId: "{{SOURCE_CART_ID}}" userId: "{{USER_ID}}" }) }
[GQL-EXEC cleanup_src]

Assertions:
[ERRORS label=add_item_src] errors[] empty
[DATA label=add_item_src] data.addItem.itemsCount = 1
[ERRORS label=merge] errors[] empty
[DATA label=merge] data.mergeCart.itemsCount >= 1
[DATA label=merge] data.mergeCart.items[?productId=@td(CFG_LAPTOP.id)].configurationItems[?sectionId={{SECTION_RAM_ID}}].productId = {{OPT_RAM_UPGRADE_ID}}
[DATA label=merge] data.mergeCart.items[?productId=@td(CFG_LAPTOP.id)].configurationItems[?sectionId={{SECTION_STORAGE_ID}}].productId = {{OPT_STORAGE_UPGRADE_ID}}

